import fs from 'fs';
import path from 'path';

const outDir = path.join(process.cwd(), 'src', 'client', 'images');
fs.mkdirSync(outDir, { recursive: true });

// The base64 string from the original reference HTML
const b64 = ``;

fs.writeFileSync(path.join(outDir, 'hero.jpg'), Buffer.from(b64, 'base64'));
fs.writeFileSync(path.join(outDir, 'claudia.jpg'), Buffer.from(b64, 'base64'));
fs.writeFileSync(path.join(outDir, 'placeholder.jpg'), Buffer.from(b64, 'base64'));

console.log('✅ Generated hero.jpg, claudia.jpg, and placeholder.jpg');
